display.text:
/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import {matchPath} from '@docusaurus/router';
import {hasProtocol} from '@docusaurus/isInternalUrl';
import {
  addLeadingSlash,
  addTrailingSlash,
  removeTrailingSlash,
} from '@docusaurus/utils-common';

import type {
  GlobalPluginData,
  GlobalVersion,
  GlobalDoc,
  ActivePlugin,
  ActiveDocContext,
  DocVersionSuggestions,
} from '@docusaurus/plugin-content-docs/client';
import type {UseDataOptions} from '@docusaurus/types';

// This code is not part of the api surface, not in ./theme on purpose

// get the data of the plugin that is currently "active"
// ie the docs of that plugin are currently browsed
// it is useful to support multiple docs plugin instances
export function getActivePlugin(
  allPluginData: {[pluginId: string]: GlobalPluginData},
  pathname: string,
  options: UseDataOptions = {},
): ActivePlugin | undefined {
  const activeEntry = Object.entries(allPluginData)
    // Route sorting: '/android/foo' should match '/android' instead of '/'
    .sort((a, b) => b[1].path.localeCompare(a[1].path))
    .find(
      ([, pluginData]) =>
        !!matchPath(pathname, {
          path: pluginData.path,
          exact: false,
          strict: false,
        }),
    );

  const activePlugin: ActivePlugin | undefined = activeEntry
    ? {pluginId: activeEntry[0], pluginData: activeEntry[1]}
    : undefined;

  if (!activePlugin && options.failfast) {
    throw new Error(
      `Can't find active docs plugin for "${pathname}" pathname, while it was expected to be found. Maybe you tried to use a docs feature that can only be used on a docs-related page? Existing docs plugin paths are: ${Object.values(
        allPluginData,
      )
        .map((plugin) => plugin.path)
        .join(', ')}`,
    );
  }

  return activePlugin;
}

export const getLatestVersion = (data: GlobalPluginData): GlobalVersion =>
  data.versions.find((version) => version.isLast)!;

export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  if (hasProtocol(pathname)) {
    return undefined;
  }

  const availableVersions = data.versions;
  const pathnameWithoutSlash = removeTrailingSlash(pathname);
  const pathnameWithSlash = addTrailingSlash(pathname);
  const normalizedPathname = addLeadingSlash(pathnameWithoutSlash);

  let lastVersion: GlobalVersion | undefined;
  const remainingVersions: GlobalVersion[] = [];
  for (const candidateVersion of availableVersions) {
    if (candidateVersion.isLast && lastVersion === undefined) {
      lastVersion = candidateVersion;
    } else {
      remainingVersions.push(candidateVersion);
    }
  }

  const orderedVersions =
    lastVersion === undefined
      ? remainingVersions
      : [...remainingVersions, lastVersion];

  for (const version of orderedVersions) {
    const versionPath = version.path;
    const versionPathWithoutSlash = removeTrailingSlash(versionPath);
    const versionPathWithSlash = addTrailingSlash(versionPath);
    const normalizedVersionPath = addLeadingSlash(versionPathWithoutSlash);
    const lowerPathname = normalizedPathname.toLowerCase();
    const lowerVersionPath = normalizedVersionPath.toLowerCase();
    const exactPathMatch =
      lowerPathname === lowerVersionPath ||
      pathnameWithSlash.toLowerCase() === versionPathWithSlash.toLowerCase();
    const sharesVersionPrefix =
      lowerVersionPath === '/' || lowerPathname.startsWith(lowerVersionPath);

    if (exactPathMatch) {
      const exactMatch = matchPath(pathname, {
        path: versionPath,
        exact: true,
        strict: false,
      });
      if (exactMatch) {
        return version;
      }
    }

    if (normalizedVersionPath === '/') {
      const rootMatch = matchPath(pathname, {
        path: versionPath,
        exact: false,
        strict: false,
      });
      if (rootMatch) {
        return version;
      }
    } else if (sharesVersionPrefix) {
      if (versionPath.endsWith('/')) {
        const trailingSlashMatch = matchPath(pathname, {
          path: versionPath,
          exact: false,
          strict: false,
        });
        if (trailingSlashMatch) {
          return version;
        }
      } else {
        const prefixMatch = matchPath(pathname, {
          path: versionPath,
          exact: false,
          strict: false,
        });
        if (prefixMatch) {
          return version;
        }
      }
    } else {
      const fallbackMatch = matchPath(pathname, {
        path: versionPath,
        exact: false,
        strict: false,
      });
      if (fallbackMatch) {
        return version;
      }
    }
  }

  return undefined;
}

export function getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  const activeVersion = getActiveVersion(data, pathname);
  const activeDoc = activeVersion?.docs.find(
    (doc) =>
      !!matchPath(pathname, {
        path: doc.path,
        exact: true,
        strict: false,
      }),
  );

  function getAlternateVersionDocs(
    docId: string,
  ): ActiveDocContext['alternateDocVersions'] {
    const result: ActiveDocContext['alternateDocVersions'] = {};
    data.versions.forEach((version) => {
      version.docs.forEach((doc) => {
        if (doc.id === docId) {
          result[version.name] = doc;
        }
      });
    });
    return result;
  }

  const alternateVersionDocs = activeDoc
    ? getAlternateVersionDocs(activeDoc.id)
    : {};

  return {
    activeVersion,
    activeDoc,
    alternateDocVersions: alternateVersionDocs,
  };
}

export function getDocVersionSuggestions(
  data: GlobalPluginData,
  pathname: string,
): DocVersionSuggestions {
  const latestVersion = getLatestVersion(data);
  const activeDocContext = getActiveDocContext(data, pathname);
  const latestDocSuggestion: GlobalDoc | undefined =
    activeDocContext.alternateDocVersions[latestVersion.name];
  return {latestDocSuggestion, latestVersionSuggestion: latestVersion};
}

