export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  if (hasProtocol(pathname)) {
    return undefined;
  }

  // Sort versions so that the most specific (longest) version path is matched
  // first. Otherwise, a version whose path is a prefix of another version's
  // path (eg "/docs" vs "/docs/version1", or even "/") would always be
  // considered as active and shadow the more specific versions.
  // See https://github.com/facebook/docusaurus/issues/10309
  // `Array#sort` is stable: versions with paths of the same length keep their
  // original order, so the first declared version is matched first.
  const sortedVersions = [...data.versions].sort(
    (a, b) =>
      removeTrailingSlash(b.path).length - removeTrailingSlash(a.path).length,
  );

  return sortedVersions.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

