import {fromPartial} from '@total-typescript/shoehorn';
import {getActiveVersion, getActiveDocContext} from '../packages/docusaurus-plugin-content-docs/src/client/docsClientUtils';
import type {GlobalVersion} from '../packages/docusaurus-plugin-content-docs/src/client/index';

const versions: GlobalVersion[] = [
  fromPartial<GlobalVersion>({name: 'current', label: 'Current', path: '/'}),
  fromPartial<GlobalVersion>({name: 'v0.1.2', label: 'v0.1.2', path: '/v0.1.2'}),
  fromPartial<GlobalVersion>({name: 'v0.2.0', label: 'v0.2.0', path: '/v0.2.0', isLast: true}),
];

const data = fromPartial({versions});

console.log('/ ->', getActiveVersion(data, '/')?.name); // current
console.log('/intro ->', getActiveVersion(data, '/intro')?.name); // current
console.log('/v0.1.2 ->', getActiveVersion(data, '/v0.1.2')?.name); // v0.1.2
console.log('/v0.1.2/intro ->', getActiveVersion(data, '/v0.1.2/intro')?.name); // v0.1.2
console.log('/v0.2.0/intro ->', getActiveVersion(data, '/v0.2.0/intro')?.name); // v0.2.0
console.log('/V0.1.2 ->', getActiveVersion(data, '/V0.1.2')?.name); // undefined (case-sensitive)
console.log(
  'docCtx /v0.1.2/intro activeVersion:',
  getActiveDocContext(data, '/v0.1.2/intro').activeVersion?.name,
);

